import { For, onMount } from "solid-js";
import { render } from "solid-js/web";

import { Header } from "#core/ui-next/components/header.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { ComponentsExample } from "#core/ui-next/sandbox/components-example.jsx";
import { SandboxBox } from "#core/ui-next/sandbox/sandbox-box.jsx";
import { SandboxNavigation } from "#core/ui-next/sandbox/sandbox-navigation.js";

import { ScrollArea } from "../components/scroll-area";

import { EffectExample } from "./effect-example";
import { HelloComponent } from "./hello-component";
import { ListExample } from "./list-example";
import { SimpleBinding } from "./simple-binding";

// import TooltipsExample from "#core/ui-next/sandbox/tooltip-example.jsx";

const locStrings = [
	"LOC_UI_OPTIONS_TITLE",
	"LOC_OPTIONS_CATEGORY_ACCESSIBILITY",
	"LOC_OPTIONS_CATEGORY_ACCESSIBILITY_DESCRIPTION",
	"LOC_OPTIONS_CATEGORY_AUDIO",
	"LOC_OPTIONS_CATEGORY_AUDIO_DESCRIPTION",
	"LOC_OPTIONS_CATEGORY_GAME",
	"LOC_OPTIONS_CATEGORY_GAME_DESCRIPTION",
	"LOC_OPTIONS_CATEGORY_GRAPHICS",
	"LOC_OPTIONS_CATEGORY_GRAPHICS_DESCRIPTION",
	"LOC_OPTIONS_CATEGORY_INPUT_DESCRIPTION",
	"LOC_OPTIONS_CATEGORY_INTERFACE",
	"LOC_OPTIONS_CATEGORY_INTERFACE_DESCRIPTION",
	"LOC_OPTIONS_CATEGORY_SYSTEM",
	"LOC_OPTIONS_CATEGORY_SYSTEM_DESCRIPTION",
	"LOC_OPTIONS_CANCEL",
	"LOC_OPTIONS_CANCEL_CHANGES",
	"LOC_OPTIONS_REVERT",
	"LOC_OPTIONS_REVERT_DESCRIPTION",
	"LOC_OPTIONS_DEFAULT",
	"LOC_OPTIONS_DEFAULTS",
	"LOC_OPTIONS_DEFAULTS_DESCRIPTION",
	"LOC_OPTIONS_ARE_YOU_SURE",
	"LOC_OPTIONS_ARE_YOU_SURE_DEFAULT",
	"LOC_OPTIONS_YES",
	"LOC_OPTIONS_NO",
	"LOC_OPTIONS_CONFIRM",
	"LOC_OPTIONS_CONFIRM_CHANGES",
	"LOC_OPTIONS_ACCEPT",
];

engine.whenReady.then(() => {
	const simpleNav = new SandboxNavigation();

	render(() => {
		let ref: HTMLDivElement | undefined;

		onMount(() => {
			simpleNav.setFocus(ref!);
		});

		return (
			<Panel
				id="sandbox-panel"
				name="Sandbox"
				class="w-full h-full flex flex-col"
				ref={ref}
			>
				<Header class="text-2xl mt-4">UI-Next Solid Test Sandbox</Header>
				<Tab class="flex flex-col flex-auto m-4">
					<Tab.TabList
						nextHotkey="nav-next"
						previousHotkey="nav-previous"
					/>
					<Tab.Output />
					<Tab.Item
						name="Components"
						title={() => "Components"}
						body={() => <ComponentsExample />}
					/>
					{/* <Tab.Item name="Tooltips" title={() => "Tooltips"} body={() => <TooltipsExample />} /> */}
					<Tab.Item
						name="Basic"
						title={() => "Basic"}
						body={() => (
							<>
								<SandboxBox class="w-96">
									<HelloComponent name="World" />
									<HelloComponent name="SolidJs" />
									<HelloComponent name="Fxs UI" />
								</SandboxBox>
								<SimpleBinding class="mx-2 mt-2" />
								<EffectExample />
							</>
						)}
					/>
					<Tab.Item
						name="List"
						title={() => "List"}
						body={() => <ListExample />}
					/>
					<Tab.Item
						name="Scrollable"
						title={() => "Proxy Scroll"}
						body={() => (
							<SandboxBox class="self-start">
								<ScrollArea
									class="w-200 h-96"
									useProxy={true}
								>
									<L10n.Stylize text="LOC_TRAIT_LEADER_ASHOKA_ABILITY_DESCRIPTION" />
									<For each={locStrings}>{(item) => <L10n.Compose text={item} />}</For>
								</ScrollArea>
							</SandboxBox>
						)}
					/>
				</Tab>
			</Panel>
		);
	}, document.getElementById("root")!);
});
